WITH cleaned AS (SELECT *, UPPER(location) AS location_upper, INITCAP(TRIM(location)) AS location_title FROM departments WHERE location IS NOT NULL), not_flagged AS (SELECT s.* FROM cleaned s WHERE NOT EXISTS (SELECT 1 FROM employees x WHERE x.dept_id = s.id AND x.full_name IS NOT NULL)), scored AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY dept_name, location ORDER BY budget, id) AS event_seq, LEAD(budget, 1) OVER (PARTITION BY dept_name ORDER BY budget, id) AS next_budget, MAX(budget) OVER (PARTITION BY dept_name) AS dept_name_max_budget FROM not_flagged), cleaned_departments AS (SELECT id, dept_name, location, budget, location_title, event_seq, next_budget, COALESCE(location, 'Unknown') AS location_filled, COALESCE(dept_name, 'UNKNOWN') AS dept_name_clean FROM scored WHERE budget <= 1622000) SELECT id, location, budget, location_title, event_seq, next_budget, location_filled, dept_name_clean, CASE WHEN location RLIKE '^(New York|Bangkok)$' THEN 'EXTENDED' ELSE 'CORE' END AS location_zone FROM cleaned_departments ORDER BY next_budget NULLS FIRST, location;
